-- DECISION: placeholder defaults until the owner sets prices (docs/plan.md §1.32): an agent with no
-- price of its own or from its template is $250.0000 a month with the 2,000 credits already in
-- allowance_credits_per_agent (now the default included credits); an extra credit is $0.0200;
-- auto-send is off, so every statement waits for the operator. The Stripe price ids, meter name and
-- price snapshots of §1.24 stay in billing_setting, unused, so the previous Worker keeps working.

-- Prices and statements are kept, never deleted: a client agent's override changes in place (and
-- every change is in agent_change); a template's price may be cleared back to the default. Agent
-- days are only inserted. Statements change their status and Stripe's ids; their lines are added
-- and removed only while the statement is a draft whose send hasn't started.
GRANT SELECT, INSERT, UPDATE, DELETE ON billing_template_price, billing_agent_price TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT ON billing_agent_day TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON billing_statement TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON billing_statement_line TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['billing_agent_price', 'billing_agent_day', 'billing_statement',
                           'billing_statement_line'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
END
$$;
