-- A statement is never deleted. What it bills (its month, credits and price of a credit) never
-- changes; its total changes only while it is a draft whose send hasn't started (adjustments). A
-- void or nothing-due statement keeps its status, and none goes back to draft.
CREATE OR REPLACE FUNCTION billing_statement_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  frozen text[] := ARRAY['id', 'tenant_id', 'period', 'period_end', 'days_in_month', 'currency',
                         'credits_used', 'credits_included', 'extra_credits', 'credit_price',
                         'created_at'];
  k text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'billing_statement rows are never deleted' USING ERRCODE = 'restrict_violation';
  END IF;
  FOREACH k IN ARRAY frozen LOOP
    IF (to_jsonb(NEW) -> k) IS DISTINCT FROM (to_jsonb(OLD) -> k) THEN
      RAISE EXCEPTION 'billing_statement.% never changes', k USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  IF NEW.total IS DISTINCT FROM OLD.total
     AND NOT (OLD.status = 'draft' AND OLD.stripe_invoice_id IS NULL) THEN
    RAISE EXCEPTION 'a statement''s total changes only while it is a draft not yet sent'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND (OLD.status IN ('void', 'nothing_due') OR NEW.status = 'draft') THEN
    RAISE EXCEPTION 'a % statement can''t become %', OLD.status, NEW.status
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER billing_statement_guard BEFORE UPDATE OR DELETE ON billing_statement
  FOR EACH ROW EXECUTE FUNCTION billing_statement_guard();
--> statement-breakpoint

-- A statement's lines are added (and adjustments removed) only while it is a draft whose send
-- hasn't started. After that a line changes once: Stripe's invoice item id is set.
CREATE OR REPLACE FUNCTION billing_statement_line_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  s_status text;
  s_invoice text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (to_jsonb(NEW) - 'stripe_invoice_item_id') IS DISTINCT FROM
         (to_jsonb(OLD) - 'stripe_invoice_item_id')
       OR (OLD.stripe_invoice_item_id IS NOT NULL
           AND NEW.stripe_invoice_item_id IS DISTINCT FROM OLD.stripe_invoice_item_id) THEN
      RAISE EXCEPTION 'billing_statement_line rows are immutable; only stripe_invoice_item_id is set, once'
        USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT status, stripe_invoice_id INTO s_status, s_invoice FROM billing_statement
    WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.statement_id ELSE NEW.statement_id END;
  IF s_status IS DISTINCT FROM 'draft' OR s_invoice IS NOT NULL THEN
    RAISE EXCEPTION 'lines change only while their statement is a draft not yet sent'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.kind <> 'adjustment' THEN
      RAISE EXCEPTION 'only adjustments are removed from a statement'
        USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER billing_statement_line_guard BEFORE INSERT OR UPDATE OR DELETE ON billing_statement_line
  FOR EACH ROW EXECUTE FUNCTION billing_statement_line_guard();
